#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe smtp-test-a-password-reset-mail. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'Example app' > site/index.txt
cat > no-link.eml <<'EOF'
From: app@example.com
To: carol@example.com
Subject: Reset your password

Open this link to choose a new password:

EOF
cat > reset-app.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Stands in for the app: makes a reset token, publishes the reset page under site/reset/, and
# mails the recipient a link to it. A fourth argument puts another token in the link, as a bug would.
# Usage: sh reset-app.sh <smtp port> <http port> <recipient> [<token for the link>]
token=$(od -An -N8 -tx1 /dev/urandom | tr -d ' \n')
mkdir -p site/reset
printf 'Choose a new password for %s.\n' "$3" > "site/reset/$token"
printf 'From: app@example.com\nTo: %s\nSubject: Reset your password\n\nOpen this link to choose a new password:\nhttp://127.0.0.1:%s/reset/%s\n' \
  "$3" "$2" "${4:-$token}" |
  curl -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt "$3" \
    -T - "smtp://127.0.0.1:$1/example.com"
EOF
cat > check-reset-link.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Reads the reset mail (the INBOX's first message) over IMAP, finds the link in it and fetches it.
# Usage: sh check-reset-link.sh <user:password> <imap port>
body=$(curl -sS -u "$1" "imap://127.0.0.1:$2/INBOX;UID=1;SECTION=TEXT") || exit $?
link=$(printf '%s\n' "$body" | tr -d '\r' | sed -n 's|^.*\(http://[^ ]*/reset/[^ ]*\).*$|\1|p' | head -n 1)
if [ -z "$link" ]; then
  echo "FAIL: no reset link in the mail"
  exit 1
fi
echo "link: $link"
curl -sS -f "$link"
EOF
surl -v --log-file surl.log --directory site --mail-domain example.com --mailbox app@example.com:apppass --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass --mailbox carol@example.com:carolpass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ http://127.0.0.1:8082/ &
sleep 1
sh reset-app.sh 8080 8082 ann@example.com && sh check-reset-link.sh ann@example.com:annpass 8081
kill $(jobs -p)
